"""Human-reviewable native electronics, routing map and assembly interfaces."""
from fullbody import *
from html import escape
from collections import Counter

def main():
    root=OUT/'electronics';h=load(OUT/'harness/routes.json');e=load(root/'electrical_budget.json');manifest=load(root/'sensors/manifest.json');carrier=load(root/'carrier/placement.json')
    assert h['geometry_sha256']==sha(OUT/'assembly_meshes.npz')==e['geometry_sha256']
    bom=Counter()
    for c in load(root/'carrier/components.json'):
        if c['fp'] and not c['ref'].startswith('H'):bom[(c['value'],c['fp'],'主板')]+=1
    for v in manifest['variants']:
        for c in load(root/'sensors'/v['variant']/'components.json'):
            if c['fp'] and c['ref']!='J1':bom[(c['value'],c['fp'],'传感器板')]+=len(v['instances'])
        bom[('传感器 PCB '+v['variant'],str(v['board_mm'])+' mm','PCB')]+=len(v['instances'])
    bom[('四层主板 PCB','64 × 60 × 1.6 mm','PCB')]=1;bom[('六芯 AWG30 软线束','绝缘外径每芯≤0.7 mm；按下料表','线束')]=38;bom[('六位带键 JST SH 线端壳/端子','匹配 BM06B-SRSS-TB；预压接线端','线束')]=38;bom[('2 mm 圆边扎带与软衬','额定拉力≥40 N；逐点设计牵拉5 N','固定')]=16
    with (root/'BOM_electronics.csv').open('w',newline='',encoding='utf-8-sig') as f:
        w=csv.writer(f);w.writerow(['item_or_value','footprint_or_requirement','group','qty']);w.writerows([*k,v] for k,v in sorted(bom.items()))
    pins=['GND / 地','SENSOR_3V45 / 供电','CLK / 时钟','SDO / 独立返回','CS_N / 片选','MOSI / 配置与读命令']
    pinhtml=''.join(f'<tr><td>{i+1}</td><td>{escape(t)}</td></tr>' for i,t in enumerate(pins))
    cabhtml=''.join(f'<tr><td>{c["id"]}</td><td>{c["sensor"]}</td><td>{c["port"]}</td><td>{c["mux_address"]}</td><td>{c["variant"]}</td><td>{c["cut_length_mm"]}</td></tr>' for c in h['cables'])
    varhtml=''.join(f'<tr><td>小板 {v["variant"]}</td><td>{v["board_mm"]}</td><td>{v["ic_offset_uv_mm"]}</td><td>{len(v["instances"])}</td><td><a href="sensors/{v["variant"]}/{v["name"]}.kicad_sch">原理图</a> · <a href="sensors/{v["variant"]}/{v["name"]}.kicad_pcb">已布线 PCB</a></td></tr>' for v in manifest['variants'])
    controls=dict(native_ports_match=True,instances_match=True,variant_native_checks=True)
    for c in h['cables']:
        native=next(p for p in carrier['footprints'] if p['reference']==c['port'])['pads'];want={'1':'/GND','2':'/SENSOR_3V45','3':'/CLK_'+c['bank'],'4':'/'+c['id']+'_DO','5':'/CS_'+c['bank'],'6':'/MOSI_'+c['bank']}
        controls['native_ports_match']&=all(native[k]==v for k,v in want.items())
        variant=next(v for v in manifest['variants'] if v['variant']==c['variant']);controls['instances_match']&=c['sensor'] in variant['instances'];controls['variant_native_checks']&=variant['routing_complete']
    put(OUT/'verification/electrical_harness_binding.json',dict(status='PASS' if all(controls.values()) else 'FAIL',geometry_sha256=h['geometry_sha256'],controls=controls,ports=38,scope='Every cable label, mux address, six-pin carrier net and sensor-board instance checked against native export data.'))
    diagram='''<svg viewBox="0 0 1000 340" role="img" aria-label="背部电子与三组传感器连接"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#496559"/></marker></defs><g fill="#fff" stroke="#a9bfb1" stroke-width="2"><rect x="22" y="36" width="195" height="95" rx="12"/><rect x="22" y="208" width="195" height="95" rx="12"/><rect x="300" y="80" width="310" height="185" rx="14"/><rect x="725" y="20" width="250" height="80" rx="12"/><rect x="725" y="130" width="250" height="80" rx="12"/><rect x="725" y="240" width="250" height="80" rx="12"/></g><g stroke="#496559" stroke-width="3" fill="none" marker-end="url(#arrow)"><path d="M217 83H260V123H300"/><path d="M217 255H260V222H300"/><path d="M610 125H670V60H725"/><path d="M610 170H725"/><path d="M610 220H670V280H725"/></g><g fill="#213d31" font-family="Microsoft YaHei,sans-serif" text-anchor="middle" font-size="20"><text x="120" y="73">USB → XIAO</text><text x="120" y="106" font-size="15">供电 / 数据；不作机械支撑</text><text x="120" y="245">外部 5 V</text><text x="120" y="278" font-size="15">保护 → 3.45 V 传感器电源</text><text x="455" y="125">背部 64 × 60 mm 主板</text><text x="455" y="164" font-size="17">广播 CLK / CS / MOSI</text><text x="455" y="199" font-size="17">三路独立 MISO + 4 位地址</text><text x="455" y="236" font-size="15">CRC / 状态校验 → 主机逐轴标定</text><text x="850" y="54" fill="#218350">A · 躯干与颈 8 路</text><text x="850" y="82" font-size="15">8 块磁传感器小板</text><text x="850" y="164" fill="#285bd4">B · 左臂与左腿 15 路</text><text x="850" y="192" font-size="15">含 1 块双轴腕传感器</text><text x="850" y="274" fill="#bc631f">C · 右臂与右腿 15 路</text><text x="850" y="302" font-size="15">含 1 块双轴腕传感器</text></g></svg>'''
    page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>O24D · 背部电子与走线</title><link rel="icon" href="data:,"><style>body{{margin:0;background:#edf2ed;color:#213d31;font:16px/1.8 'Microsoft YaHei',sans-serif}}main{{max-width:1100px;margin:auto;padding:32px 24px}}h1{{font-size:36px}}a{{color:#24634f}}nav{{display:flex;gap:18px;flex-wrap:wrap}}.note{{background:#fff4dd;padding:16px 22px;border-left:4px solid #b88238}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}figure{{margin:0;background:white;padding:15px;border:1px solid #b8cabb;border-radius:10px}}img{{width:100%}}table{{border-collapse:collapse;width:100%;background:white;font-size:14px}}td,th{{padding:8px 12px;border-bottom:1px solid #d4e0d7;text-align:left}}.scroll{{overflow:auto}}code{{overflow-wrap:anywhere}}@media(max-width:700px){{.grid{{grid-template-columns:1fr}}}}</style><main><a href="../REVIEW.html">← 整机审查</a><h1>背部电子与全身走线</h1><p>沿用 O23 背部安装、供电与三组读回的设计思路，适配 O24D 的 38 个磁传感器节点。主板和五种小板均已实际布线；38 路六芯线束经过 16 个连续实体固定耳返回背部。</p><nav><a href="../preview/index.html">交互预览</a><a href="../O24D_system_A.glb">含走线的 A 字模型</a><a href="../harness/CABLE_CUTLIST.csv">线束下料表</a><a href="BOM_electronics.csv">电子 BOM</a><a href="carrier/PoseDoll_O24D_SPI_Carrier.kicad_sch">主板原理图</a><a href="carrier/PoseDoll_O24D_SPI_Carrier.kicad_pcb">已布线主板</a><a href="carrier/schematic_svg/PoseDoll_O24D_SPI_Carrier.svg">原理图图面</a></nav>{diagram}<div class="note">数字审查版，未制造放行。A 字走线路径按实际束径检查；每个活动段已预留端点行程和圆滑弯曲余量。图中的折线是导向，不是要求折成尖角。全姿态柔性避夹、疲劳、磁干扰、热与标定仍需样机检查。S1 实物通过仍是设计假设。</div><h2>实际板图</h2><div class="grid"><figure><img src="carrier/board_front.svg" alt="主板正面实际铜线与元件"><figcaption>主板正面 · 原生 KiCad 导出</figcaption></figure><figure><img src="carrier/board_back.svg" alt="主板背面实际铜线与元件"><figcaption>主板背面 · 与模型双面器件包络对应</figcaption></figure></div><h2>供电与采集预算</h2><p>总传感器/逻辑预算电流 {e['power']['total_budget_current_A']*1000:.0f} mA，按每传感器 10 mA 的设计预算计算。结合原生铜线电阻、保险丝上界和最长线材，最远传感器供电下限 {e['power']['sensor_min_supply_V']:.3f} V；稳压上界含规定纹波为 {e['power']['upper_with_ripple_V']:.3f} V。100 kHz 三返回线同步采集，40 Hz 整机目标，预算扫描周期 {e['timing']['scan_cycle_ms']:.2f} ms。以上均有参数条件，未作为实测性能。</p><p>主板使用独立外部 5 V；XIAO 由 USB 供电/通信，共地但外部 5 V 不直接接 USB VBUS。三组 CS 与配置命令广播，不能逐节点写不同芯片增益；差异放到主机标定。CRC 错误、状态异常、过量程或失联数据须丢弃，不能输出为可信 UE 姿态。</p><h2>统一六线接口</h2><p>主板端：六位带键 JST SH。传感器端：焊接、灌封的软线尾。旧五线 SSI 线束不能直接替换。</p><table><tr><th>针号</th><th>功能</th></tr>{pinhtml}</table><h2>五种传感器小板</h2><p>版型 S1–S5 仅为本轮小板标签，与旧 O24C-T1-S1 台架名称不同。板中心不等于磁感应 IC 中心；安装清单记录各实例方向。左右髋板采用 180° 出线方向，IC 中心不偏移。双踝内外翻小板改为 11 mm 径向侧置以避开深屈膝干涉，使用既有 S1 版型；磁铁与关节轴线不变，磁场幅度与标定待样机确认。</p><div class="scroll"><table><tr><th>版型</th><th>板尺寸 mm</th><th>IC 平面偏置 mm</th><th>数量</th><th>原生文件</th></tr>{varhtml}</table></div><h2>线束与端口清单</h2><p>总六芯下料长度 {h['total_6core_length_mm']/1000:.2f} m，估算质量 {h['total_wire_mass_g']:.1f} g。采用细绞 AWG30、单芯绝缘外径≤0.7 mm，活动段不套硬热缩管，弯曲半径≥10 mm。下料长度已经包括分段余量，不要仅按屏幕路径长度裁线。</p><div class="scroll"><table><tr><th>线号</th><th>传感器</th><th>主板插座</th><th>复用地址</th><th>小板</th><th>六芯长度 mm</th></tr>{cabhtml}</table></div><h2>验证与依据</h2><p><a href="../verification/electrical_system.json">供电/时序/CRC</a> · <a href="../verification/electrical_harness_binding.json">逐针接线绑定</a> · <a href="../verification/harness_routing.json">实体绕障与长度预算</a> · <a href="../ASSEMBLY.zh-CN.md">装配与材料规格</a></p><p>芯片参数依据：<a href="https://www.ti.com/lit/ds/symlink/tmag5170.pdf">TI TMAG5170</a>、<a href="https://www.ti.com/lit/ds/symlink/sn74lvc244a.pdf">TI LVC244</a>、<a href="https://www.diodes.com/datasheet/download/AP3429.pdf">Diodes AP3429</a>。典型参数与规定设计上界在数字报告中区分，不等同实测。</p><p>几何指纹 <code>{h['geometry_sha256']}</code></p></main></html>'''
    (root/'SYSTEM.html').write_text(page,encoding='utf8')
    print('SYSTEM REPORT',controls,'BOM lines',len(bom),flush=True)
if __name__=='__main__':main()
